// ---------------------------------------------------------------------------
// WF4 · Errores no atrapados · Traducir los datos del Error Trigger a los 5
// campos que espera WF4_aviso_tecnico.
// Entrada ($json): lo que entrega el Error Trigger (forma de la documentación
// oficial de n8n):
//   - caso normal: workflow.name, execution.id, execution.lastNodeExecuted,
//     execution.error.message
//   - si falló el DISPARADOR del flujo: no hay execution completo; los datos
//     vienen en trigger.node y trigger.error
// Salida: { flujo, nodo, mensaje_error, oportunidad_id, ejecucion_id }.
// ---------------------------------------------------------------------------

// "?? {}": si falta una parte, un objeto vacío, para que las líneas de abajo
// no fallen al leer dentro de ella.
const wf = $json.workflow ?? {};    // datos del flujo que ha fallado
const ex = $json.execution ?? {};   // datos de la ejecución que ha fallado
const tr = $json.trigger ?? {};     // solo existe si falló su disparador

// Nombre del flujo que ha fallado (p. ej. "WF2_aviso_gate").
const flujo = wf.name ?? 'flujo desconocido';

// Paso que ha fallado: el último nodo ejecutado; si falló el disparador, el
// nombre del disparador. "?." lee dentro sin romper si la parte no existe.
const nodo = ex.lastNodeExecuted ?? tr.node?.name ?? 'disparador';

// Texto del error: el de la ejecución o, si no hay, el del disparador.
const mensaje_error = ex.error?.message ?? tr.error?.message ?? 'Error sin mensaje';

// Número de la ejecución. Según la documentación, solo existe si la ejecución
// se guardó en la base de datos de n8n; si no, se indica.
// String(): WF4_aviso_tecnico espera este campo como texto.
const ejecucion_id = (ex.id !== undefined && ex.id !== null) ? String(ex.id) : 'no guardada';

// El Error Trigger no sabe a qué oportunidad afectaba el error: se envía null
// y WF4_aviso_tecnico lo mostrará como un guion.
return { json: { flujo, nodo, mensaje_error, oportunidad_id: null, ejecucion_id } };
